// cepm helper: reloads unpacked extensions on request from the cepm native
// messaging host. Generated by "cepm setup"; do not edit by hand.

const HOST_NAME = "com.github.be_hase.cepm";
const KEEPALIVE_ALARM = "cepm-keepalive";
// Replaced by cepm when it writes this file; the value lives in Go (see
// helperext.Protocol). The manifest version cannot stand in for it: a
// refresh that updates manifest.json and then fails on this file would
// leave old code announcing a new version.
const HELPER_PROTOCOL = 0;

let port = null;
let backoffMs = 1000;

function connect() {
  if (port) return;
  port = chrome.runtime.connectNative(HOST_NAME);
  port.onMessage.addListener(onMessage);
  port.onDisconnect.addListener(() => {
    // Fires both when the host exits (Chrome quitting) and when the host
    // binary is missing/misconfigured (chrome.runtime.lastError set).
    void chrome.runtime.lastError;
    port = null;
    scheduleReconnect();
  });
  post({
    type: "hello",
    helperVersion: chrome.runtime.getManifest().version,
    protocol: HELPER_PROTOCOL,
  });
}

function scheduleReconnect() {
  // Best-effort: the service worker may be killed before this fires, in
  // which case the keepalive alarm below revives us and reconnects.
  const delay = backoffMs;
  backoffMs = Math.min(backoffMs * 2, 60000);
  setTimeout(connect, delay);
}

function post(msg) {
  if (!port) return;
  try {
    port.postMessage(msg);
  } catch (e) {
    // Port died between the check and the send; onDisconnect will handle it.
  }
}

async function onMessage(msg) {
  switch (msg.type) {
    case "helloAck":
      backoffMs = 1000;
      break;
    case "ping":
      post({ type: "pong", seq: msg.seq });
      break;
    case "reload":
      await handleReload(msg);
      break;
    case "listExtensions":
      await handleList(msg);
      break;
    case "uninstall":
      await handleUninstall(msg);
      break;
  }
}

// UNINSTALL_HEARTBEAT_MS paces the "the dialog is still open" messages. The
// host waits on these instead of a clock: nothing closes Chrome's dialog
// when a deadline expires, and cepm holds the update lock for exactly as
// long as the dialog is up.
const UNINSTALL_HEARTBEAT_MS = 5000;

async function handleUninstall(msg) {
  // Chrome itself shows a confirmation dialog; the user stays in control.
  let status = "uninstalled";
  let error = "";
  const beat = setInterval(() => {
    post({ type: "uninstallPending", requestId: msg.requestId });
  }, UNINSTALL_HEARTBEAT_MS);
  try {
    await chrome.management.uninstall(msg.extensionId, {
      showConfirmDialog: true,
    });
  } catch (e) {
    // Chrome reports these as free-text messages ("Failed to find extension
    // with id ...", "Extension ... uninstall canceled by user."), so match
    // generously and treat anything unrecognised as a real error.
    const detail = String((e && e.message) || e);
    if (/cancel/i.test(detail)) {
      status = "cancelled";
    } else if (/failed to find|no such|not (found|installed)/i.test(detail)) {
      status = "not_installed";
    } else {
      status = "error";
      error = detail;
    }
  } finally {
    clearInterval(beat);
  }
  post({ type: "uninstallResult", requestId: msg.requestId, status, error });
}

// Ids this helper disabled and has not yet re-enabled. Persisted, because
// Chrome can kill an MV3 worker between the setEnabled(false) and the
// setEnabled(true) of a reload: without the marker the extension stays off
// forever, and every later attempt reads that as the user's own choice
// ("skipped_disabled"). chrome.storage.local survives browser restarts too,
// so the recovery below also fixes a crash the user rode out by quitting.
const INFLIGHT_KEY = "cepm-reload-inflight";

// storage has no transactions and reloads run concurrently: marker updates
// are chained so one id's removal cannot overwrite another id's addition.
let markerChain = Promise.resolve();
function updateInflight(mutate) {
  const next = markerChain.then(async () => {
    const got = await chrome.storage.local.get(INFLIGHT_KEY);
    const marks = got[INFLIGHT_KEY] || {};
    mutate(marks);
    await chrome.storage.local.set({ [INFLIGHT_KEY]: marks });
  });
  markerChain = next.catch(() => {});
  return next;
}

// Work on one extension id runs one at a time. Recovery at worker start and
// a reload arriving on the port would otherwise interleave: recovery reads
// "already enabled", the reload then marks the id and disables it, and
// recovery deletes that marker. A worker death right there leaves the
// extension switched off with nothing recording that cepm switched it off,
// and every later attempt reads it as the user's own choice
// ("skipped_disabled") — permanently. Chains are per id, so unrelated
// extensions still reload in parallel.
const idChains = new Map();
function withExtension(id, fn) {
  const prev = idChains.get(id) || Promise.resolve();
  const next = prev.then(fn, fn); // a failed predecessor must not block us
  idChains.set(
    id,
    next.catch(() => {}),
  );
  return next;
}

async function isInflight(id) {
  try {
    const got = await chrome.storage.local.get(INFLIGHT_KEY);
    return !!(got[INFLIGHT_KEY] || {})[id];
  } catch (e) {
    return false;
  }
}

// Finish reloads a dead worker left half-done. Everything still marked was
// disabled by us, so re-enabling restores the user's world, never overrides
// it. Runs at every worker start.
async function recoverInflight() {
  let ids;
  try {
    const got = await chrome.storage.local.get(INFLIGHT_KEY);
    ids = Object.keys(got[INFLIGHT_KEY] || {});
  } catch (e) {
    return; // storage unavailable; the markers keep for the next start
  }
  for (const id of ids) {
    await withExtension(id, async () => {
      // Re-read inside the critical section. The list above was taken
      // before any of this could be queued, so the marker may since have
      // been cleared by a reload that finished — or set by one that is
      // about to run, whose marker is not ours to delete.
      if (!(await isInflight(id))) return;
      let settled = true;
      try {
        const info = await chrome.management.get(id);
        if (!info.enabled) await chrome.management.setEnabled(id, true);
      } catch (e) {
        // get() failing means the extension is gone — settled. A failed
        // re-enable (broken manifest in the pulled commit) keeps the
        // marker, so the attempt after the next pull still knows the
        // disable was ours.
        settled = !(await isStillThere(id));
      }
      if (settled) {
        try {
          await updateInflight((m) => {
            delete m[id];
          });
        } catch (e) {}
      }
      // One id that cannot be settled must not skip the rest.
    }).catch(() => {});
  }
}

async function isStillThere(id) {
  try {
    await chrome.management.get(id);
    return true;
  } catch (e) {
    return false;
  }
}

async function handleReload(msg) {
  // Dedupe: two concurrent disable/enable cycles for one id interleave into
  // racy result rows. Array.isArray keeps a malformed frame from throwing
  // (an unhandled rejection here reads as a silent CLI timeout upstream).
  const ids = Array.isArray(msg.extensionIds) ? [...new Set(msg.extensionIds)] : [];
  // Reload concurrently: the host's reply timeout does not grow with the
  // number of managed extensions.
  const results = await Promise.all(ids.map((id) => reloadOne(id)));
  post({ type: "reloadResult", requestId: msg.requestId, results });
}

// reloadOne serializes against recovery (and against another reload of the
// same id) so the marker it sets cannot be cleared by work that decided what
// to do before this reload started.
function reloadOne(id) {
  return withExtension(id, () => reloadOneLocked(id));
}

async function reloadOneLocked(id) {
  if (id === chrome.runtime.id) {
    // Reloading ourselves would tear down the native messaging port, and
    // Chrome does not reliably restart this worker afterwards.
    return { id, status: "skipped_self" };
  }
  let info;
  try {
    info = await chrome.management.get(id);
  } catch (e) {
    return { id, status: "not_installed" };
  }
  if (info.installType !== "development") {
    // cepm only ever manages unpacked extensions; refuse to touch anything
    // the user installed from the Web Store.
    return { id, status: "skipped_not_unpacked" };
  }
  if (!info.enabled) {
    if (await isInflight(id)) {
      // Disabled by us, on an attempt the worker did not survive: finishing
      // the re-enable is the reload the user is owed.
      return finishEnable(id);
    }
    // The user turned it off in chrome://extensions; re-enabling it here
    // would override that on every update.
    return { id, status: "skipped_disabled" };
  }
  try {
    await updateInflight((m) => {
      m[id] = true;
    });
  } catch (e) {
    // Refuse rather than reload without crash cover. An unmarked disable
    // that then fails to re-enable (a broken manifest in the pulled
    // commit, a worker death) is indistinguishable from the user's own
    // choice, so every later attempt would answer "skipped_disabled" and
    // the extension would stay off for good. Nothing has been touched
    // yet; failing here is the safe direction.
    return {
      id,
      status: "error",
      error: "could not record the reload in chrome.storage; not touching the extension: " + String((e && e.message) || e),
    };
  }
  try {
    // Disabling and re-enabling an unpacked extension makes Chrome re-read
    // its files from disk.
    await chrome.management.setEnabled(id, false);
  } catch (e) {
    await clearInflight(id);
    return { id, status: "error", error: String((e && e.message) || e) };
  }
  try {
    await chrome.management.setEnabled(id, true);
    await clearInflight(id);
    return { id, status: "reloaded" };
  } catch (e) {
    // Never leave an extension disabled because of us: a broken manifest in
    // a pulled commit can make re-enabling fail.
    const detail = String((e && e.message) || e);
    try {
      await chrome.management.setEnabled(id, true);
      await clearInflight(id);
      return { id, status: "reloaded" };
    } catch (e2) {
      // The marker stays: recovery (or the attempt after the next pull)
      // keeps knowing this disable was ours, not the user's.
      return {
        id,
        status: "error",
        error: detail + " — the extension is now DISABLED in Chrome",
      };
    }
  }
}

async function finishEnable(id) {
  try {
    await chrome.management.setEnabled(id, true);
    await clearInflight(id);
    return { id, status: "reloaded" };
  } catch (e) {
    return {
      id,
      status: "error",
      error: String((e && e.message) || e) + " — the extension is now DISABLED in Chrome",
    };
  }
}

// clearInflight is best-effort by design, which leaves one known gap: if
// only this delete fails, a marker outlives its reload, and should the user
// then disable the extension by hand, the next worker start reads the stale
// marker as "we disabled it" and switches it back on. Telling that stale
// marker apart from a real half-done reload would need information storage
// cannot promise to hold — the same storage that just failed — so the gap
// is accepted rather than half-closed.
async function clearInflight(id) {
  try {
    await updateInflight((m) => {
      delete m[id];
    });
  } catch (e) {}
}

async function handleList(msg) {
  let extensions = [];
  let error = "";
  try {
    const all = await chrome.management.getAll();
    extensions = all
      .filter((e) => e.installType === "development" && e.type === "extension")
      .map((e) => ({
        id: e.id,
        name: e.name,
        version: e.version,
        enabled: e.enabled,
      }));
  } catch (e) {
    // Report the failure: "no extensions" and "could not look" lead to very
    // different decisions upstream (cleanup would drop its records).
    error = String((e && e.message) || e);
  }
  post({ type: "listResult", requestId: msg.requestId, extensions, error });
}

chrome.runtime.onStartup.addListener(connect);
chrome.runtime.onInstalled.addListener(connect);
chrome.alarms.create(KEEPALIVE_ALARM, { periodInMinutes: 0.5 });
chrome.alarms.onAlarm.addListener((alarm) => {
  if (alarm.name === KEEPALIVE_ALARM) connect();
});
recoverInflight();
connect();
